import re, glob
files = ['/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat'] + glob.glob('/app/varsea/*/*.bin')
heads, tails = set(), set()
for fn in files:
    d = open(fn,'rb').read()
    for m in re.finditer(rb'8XD[0-9A-Z]+', d):
        if len(m.group())>=6: heads.add(m.group().decode())
    for m in re.finditer(rb'[0-9A-Z]+W54', d):
        if len(m.group())>=6: tails.add(m.group().decode())
print('HEADS:', heads)
print('TAILS:', tails)
cands = []
for h in heads:
    for t in tails:
        p = h + t
        if len(p)==23 and p.startswith('8XD') and p.endswith('W54') and re.fullmatch(r'[A-Z0-9]+', p):
            cands.append(p)
cands = sorted(set(cands))
print('CANDIDATES:', cands)
with open('/app/recovered_passwords.txt','w') as f:
    for p in cands:
        f.write(p + '\n')
print('WROTE', len(cands), 'password(s)')
